package com.nextrade.common.util; public final class SafeStrings {private SafeStrings(){} public static String lower(String s){return s==null?null:s.trim().toLowerCase(java.util.Locale.ROOT);} public static String upper(String s){return s==null?null:s.trim().toUpperCase(java.util.Locale.ROOT);} public static String mask(String s,int visible){if(s==null)return null;if(s.length()<=visible)return "*".repeat(s.length());return s.substring(0,visible)+"*".repeat(s.length()-visible);}}